    if has_comma and has_dot:
        dec=',' if s.rfind(',')>s.rfind('.') else '.'
        grouping='.' if dec==',' else ','
        s=s.replace(grouping,'')
        j=s.rfind(dec)
        s=s[:j].replace(dec,'')+'.'+s[j+1:]
    elif has_comma or has_dot:
        dec=',' if has_comma else '.'
        j=s.rfind(dec)
        if len(s)-j-1==2:
            s=s[:j].replace(dec,'')+'.'+s[j+1:]
        else:s=s.replace(dec,'')
    return (-1 if neg else 1)*float(s)
def getnotes(s):
    def m(pattern):return re.search(pattern,s,re.I)
    items=m(r'\bitems\s*=\s*(-?\d+)')
    adj=m(r'\badj\s*=\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*%')
    fee=m(r'\bfee\s*=\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))')
    waive=m(r'\bwaive\s*=\s*true\b') is not None
    return (int(items.group(1)) if items else None,float(adj.group(1))/100 if adj else 0,float(fee.group(1)) if fee else 0,waive)
for i,r in enumerate(rows):
    base=amount(r['amount_str']);items,adj,fee,waive=getnotes(r['notes'])
    net=base*(1+adj)+fee
    if waive and not math.isnan(base):net=0.
    r.update(row_i=i,base=base,items=items,adj=adj,fee=fee,waive=waive,net=net)
chosen={}
for r in rows:
    k=r['record_id']
    prev=chosen.get(k)
    if prev is None or (r['event_time'],math.isfinite(r['net']),-r['row_i'])>(prev['event_time'],math.isfinite(prev['net']),-prev['row_i']):chosen[k]=r
x=[r for r in chosen.values() if '2025-10-01T00:00:00Z' <= r['event_time'] <= '2025-12-31T23:59:59Z' and r['channel'].casefold()!='phone' and math.isfinite(r['net'])]
print('chosen',len(chosen),'filtered',len(x),'channels',collections.Counter(r['channel'] for r in x))
groups=collections.defaultdict(list)
for r in x: groups[(r['region'],r['event_time'][:7])].append(r)
print('groups',len(groups),'sizes',collections.Counter(map(len,groups.values())))
for rs in groups.values():
    med=statistics.median(r['net'] for r in rs)
    mad=statistics.median(abs(r['net']-med) for r in rs)
    for r in rs:
        r['med']=med;r['mad']=mad;r['rz']=0 if mad==0 else 0.6745*(r['net']-med)/mad
        r['score']=abs(r['rz'])*math.log1p(max(1,r['items'] if r['items'] is not None else 1))
x.sort(key=lambda r:(-r['score'],-abs(r['rz']),r['event_time'],r['record_id']),reverse=False)
# Need descending time but ascending ID; make ordinal negative
x.sort(key=lambda r:(-r['score'],-abs(r['rz']),-datetime.fromisoformat(r['event_time'].replace('Z','+00:00')).timestamp(),r['record_id']))
for r in x[:20]: print(r['record_id'],r['event_time'],r['region'],repr(r['channel']),repr(r['amount_str']),'net',round(r['net'],4),'items',r['items'],'median',round(r['med'],4),'mad',round(r['mad'],4),'rz',round(r['rz'],4),'score',round(r['score'],4),'row',r['row_i'])
